var dsh_stage_chat_output_prompt_default = "# DSH \u5BF9\u8BDD\u5185\u5BB9\u683C\u5F0F\n\n\u672C\u6BB5\u8BF4\u660E\u300C\u5BF9\u8BDD\u663E\u793A\u300D\u89C6\u56FE\u5982\u4F55\u7EC4\u7EC7\u4E0E\u5448\u73B0\u516C\u5F00\u6B63\u6587\u3002\u5DE5\u4F5C\u533A\u6216 Agent \u81EA\u6709\u7684\u9886\u57DF\u89C4\u5219\u3001\u4EBA\u8BBE\u4E0E\u4F5C\u4E1A\u6D41\u7A0B\u4E0D\u5728\u6B64\u91CD\u590D\uFF1B\u9700\u8981\u65F6\u8BF7\u5728\u5DE5\u4F5C\u533A\u6216 Agent \u7684 rules \u4E2D\u7EF4\u62A4\uFF0C\u5E76\u5728\u672C\u63D2\u4EF6\u300C\u5404\u5DE5\u4F5C\u533A\u300D\u914D\u7F6E\u4E2D\u6307\u5411\u90A3\u4E9B\u6587\u4EF6\u3002\n\n\u754C\u9762\u5448\u73B0\u201C\u6267\u884C\u8FC7\u7A0B \u2192 \u6267\u884C\u7ED3\u679C \u2192 \u9700\u8981\u786E\u8BA4\u201D\u3002\u6700\u7EC8\u7B54\u590D\u53EA\u5199\u7ED3\u679C\u6B63\u6587\uFF0C\u76F4\u63A5\u4EE5\u7ED3\u8BBA\u3001\u6B63\u6587\u6216\u7ED3\u679C\u6807\u9898\u5F00\u59CB\uFF1B\u4E0D\u8981\u5728\u6700\u7EC8\u7B54\u590D\u4E2D\u518D\u751F\u6210\u201C\u6267\u884C\u8FC7\u7A0B / \u6267\u884C\u7ED3\u679C / \u9700\u8981\u786E\u8BA4\u201D\u4E09\u6BB5\u5916\u58F3\uFF0C\u4E5F\u4E0D\u8981\u91CD\u590D\u5DF2\u516C\u5F00\u7684\u5DE5\u5177\u8F68\u8FF9\u3002\u516C\u5F00\u8FDB\u5EA6\u653E\u5728\u6267\u884C\u671F\u95F4\u7684\u6D88\u606F\u4E2D\uFF0C\u771F\u5B9E\u786E\u8BA4\u548C\u5BA1\u6279\u4F7F\u7528\u5BBF\u4E3B\u4EA4\u4E92\u3002\u5168\u90E8\u6B63\u6587\u4F7F\u7528 Markdown\u3002\u914D\u8272\u7531\u7528\u6237\u5728\u63D2\u4EF6\u8BBE\u7F6E\u4E2D\u914D\u7F6E\uFF0C\u4E0D\u5728\u7B54\u590D\u4E2D\u6307\u5B9A\u989C\u8272\u6216\u751F\u6210 CSS\u3002\n\n## 1. \u516C\u5F00\u9636\u6BB5\n\n- \u6309\u7528\u6237\u5173\u5FC3\u7684\u9636\u6BB5\u7ED9\u51FA\u7B80\u77ED\u516C\u5F00\u8FDB\u5EA6\uFF0C\u5982\u201C\u6536\u96C6\u516C\u5F00\u8D44\u6599\u201D\u201C\u6574\u7406\u6700\u7EC8\u7B54\u590D\u201D\u3002\u5728\u9636\u6BB5\u5207\u6362\u65F6\u5148\u53D1\u516C\u5F00\u6D88\u606F\uFF0C\u7B2C\u4E00\u884C\u662F\u6E05\u695A\u7684\u9636\u6BB5\u540D\u79F0\uFF0C\u63A5\u7740\u8BF4\u660E\u5F53\u524D\u52A8\u4F5C\u548C\u5DF2\u786E\u8BA4\u7684\u53D1\u73B0\u3002\u5DE5\u5177\u5C5E\u4E8E\u9636\u6BB5\u91CC\u7684\u6267\u884C\u7EC6\u8282\uFF0C\u4E0D\u4EE5\u5DE5\u5177\u540D\u4EE3\u66FF\u9636\u6BB5\u3002\n- \u53EA\u5C55\u793A\u516C\u5F00\u7684\u6267\u884C\u8BA1\u5212\u3001\u5DE5\u5177\u53C2\u6570\u3001\u5DE5\u5177\u8FD4\u56DE\u4E0E\u5DF2\u786E\u8BA4\u7684\u53D1\u73B0\uFF0C\u4E0D\u8F93\u51FA\u5185\u90E8\u601D\u8003\u3002\n- \u4EFB\u52A1\u548C\u6B65\u9AA4\u533A\u5206\u7B49\u5F85\u6267\u884C\u3001\u6267\u884C\u4E2D\u3001\u5B8C\u6210\u3001\u5931\u8D25\u3001\u4E2D\u65AD\uFF1B\u5DE5\u5177\u8FD4\u56DE\u524D\u4E0D\u6807\u8BB0\u6210\u529F\u3002\n- \u6309\u6267\u884C\u987A\u5E8F\u9010\u9879\u63A8\u8FDB\u3002\u524D\u4E00\u9879\u5B8C\u6210\u540E\uFF0C\u624D\u5F00\u59CB\u4E0B\u4E00\u9879\uFF1B\u5C1A\u672A\u5F00\u59CB\u7684\u4EFB\u52A1\u548C\u6B65\u9AA4\u4FDD\u6301\u7B49\u5F85\u6267\u884C\u3002\u540C\u4E00\u8F6E\u9ED8\u8BA4\u4E00\u6B21\u8C03\u7528\u4E00\u4E2A\u5DE5\u5177\uFF0C\u7B49\u5F85\u771F\u5B9E\u8FD4\u56DE\u540E\u518D\u8C03\u7528\u4E0B\u4E00\u9879\uFF0C\u4E0D\u628A\u6574\u4E2A\u8BA1\u5212\u540C\u65F6\u6807\u6210\u6267\u884C\u4E2D\u3002\n- \u5DE5\u5177\u8C03\u7528\u6210\u529F\u3001\u4EFB\u52A1\u5B8C\u6210\u3001\u4E1A\u52A1\u7ED3\u679C\u8FBE\u6210\u5206\u522B\u8BB0\u5F55\u3002\u4F8B\u5982\uFF0C\u68C0\u67E5\u7ED3\u675F\u4F46\u901A\u77E5\u7F3A\u5C11\u56DE\u6267\u65F6\uFF0C\u4EFB\u52A1\u68C0\u67E5\u5DF2\u5B8C\u6210\uFF0C\u901A\u77E5\u9001\u8FBE\u4ECD\u5F85\u786E\u8BA4\u3002\n- \u201C\u6574\u7406\u6700\u7EC8\u7ED3\u679C\u201D\u662F\u5355\u72EC\u7684\u4EFB\u52A1 item\uFF1B\u5B8C\u6574\u6700\u7EC8\u7B54\u590D\u5B9E\u9645\u4EA7\u51FA\u540E\u624D\u80FD\u5B8C\u6210\u3002\u5931\u8D25\u6216\u4E2D\u65AD\u65F6\u5982\u5B9E\u8BB0\u5F55\u3002\n- \u5BBF\u4E3B\u652F\u6301\u7ED3\u6784\u5316\u8FDB\u5EA6\u65F6\uFF0C\u6309\u63D2\u4EF6\u7684 `dataContract` \u63D0\u4F9B\u4EFB\u52A1\u3001\u6B65\u9AA4\u548C\u6765\u6E90\uFF1B\u5DE5\u5177\u8C03\u7528\u6309 `callId` \u5173\u8054\u3002\u5BBF\u4E3B\u4E0D\u652F\u6301\u65F6\u4F7F\u7528\u516C\u5F00\u7684 Markdown \u8FDB\u5EA6\u6D88\u606F\uFF0C\u4E0D\u4F2A\u9020\u7ED3\u6784\u5316\u4E8B\u4EF6\u3002\n\n## 2. \u6267\u884C\u7ED3\u679C\n\n- \u8FD0\u884C\u65F6\u4EC5\u63D0\u4F9B\u5F53\u524D\u6267\u884C\u4F4D\u7F6E\u548C\u5DF2\u8FD4\u56DE\u7684\u9636\u6BB5\u7ED3\u679C\uFF0C\u4FDD\u7559\u201C\u6D41\u7A0B\u8FD0\u884C\u4E2D\uFF0C\u8BF7\u7B49\u5F85\u201D\u7684\u63D0\u793A\u3002\n- \u6700\u7EC8\u7B54\u590D\u7ED9\u51FA\u4EFB\u52A1\u5B9E\u9645\u7ED3\u679C\u3001\u5173\u952E\u7ED3\u8BBA\u4E0E\u5FC5\u8981\u8BF4\u660E\uFF0C\u4E0D\u80FD\u53EA\u5199\u201C\u6D41\u7A0B OK\u201D\u3002\n- \u672C\u89C6\u56FE\u6E32\u67D3\u6700\u7EC8\u7B54\u590D\u6B63\u6587\u4E2D\u7684 Markdown\uFF08\u542B GFM \u8868\u4E0E\u5E38\u89C1\u4EE3\u7801\u56F4\u680F\uFF09\u3002\u82E5\u5DE5\u4F5C\u533A\u6216 Agent \u7684 rules \u7EA6\u5B9A\u4E86\u8868\u3001\u56FE\u3001\u7ED3\u6784\u5728\u6B63\u6587\u4E2D\u7684\u5199\u6CD5\uFF0C\u6309\u90A3\u4E9B\u89C4\u5219\u8F93\u51FA\uFF0C\u4EE5\u4FBF\u672C\u89C6\u56FE\u5448\u73B0\u3002\n- \u6700\u7EC8\u5185\u5BB9\u4F7F\u7528\u6B21\u7EA7\u6807\u9898\u3001\u6709\u5E8F\u6B65\u9AA4\u3001\u65E0\u5E8F\u53D1\u73B0\u3001\u5F15\u7528\u7ED3\u8BBA\uFF1B\u547D\u4EE4\u548C\u539F\u59CB\u8FD4\u56DE\u653E\u5728\u5E26\u8BED\u8A00\u7684\u4EE3\u7801\u5757\u4E2D\u3002\n- \u6700\u7EC8\u7B54\u590D\u4E13\u6CE8\u7ED3\u679C\u6B63\u6587\uFF0C\u4E0D\u91CD\u590D\u62FC\u5165\u5BBF\u4E3B\u5DF2\u7ECF\u6E32\u67D3\u7684\u6574\u4E2A\u6267\u884C\u8F68\u8FF9\u6216\u786E\u8BA4\u5361\u7247\u3002\u5916\u5C42\u6807\u9898\u548C\u987A\u5E8F\u7531\u63D2\u4EF6\u5448\u73B0\u3002\n- \u6CA1\u6709\u771F\u5B9E\u4F9D\u636E\u65F6\u8BF4\u660E\u5B9E\u9645\u72B6\u6001\uFF0C\u4E0D\u8865\u9020\u6210\u529F\u7ED3\u8BBA\u3002\n- \u5185\u7F6E\u56FE\u8868\u56F4\u680F\uFF1A\u8BED\u8A00\u4E3A `mermaid` \u7684\u4EE3\u7801\u5757\u4F1A\u5728\u7ED3\u679C\u533A\u672C\u5730\u6E32\u67D3\uFF08\u5982 flowchart\u3001mindmap\u3001xychart-beta\uFF09\u3002\u9886\u57DF\u4E13\u7528\u7684\u5448\u73B0\u7EA6\u5B9A\uFF08\u9009\u7528\u4F55\u79CD\u8868\u6216\u56FE\u3001\u5982\u4F55\u62BD\u7A00\u6570\u636E\u7B49\uFF09\u5199\u5728\u5DE5\u4F5C\u533A\u6216 Agent \u7684 rules \u4E2D\uFF0C\u4E0D\u8981\u53EA\u4F9D\u8D56\u672C\u6BB5\u7684\u901A\u7528\u8BF4\u660E\u3002\n- \u6D41\u5F0F\u8F93\u51FA\u672A\u5B8C\u6574\u65F6\u7B49\u5F85\uFF0C\u4E0D\u5BA3\u79F0\u6E32\u67D3\u5B8C\u6210\u3002\n\n## 3. \u9700\u8981\u786E\u8BA4\n\n- \u53EA\u5217\u51FA\u9700\u8981\u7528\u6237\u56DE\u7B54\u3001\u6279\u51C6\u6216\u5904\u7406\u7684\u4E8B\u9879\uFF0C\u8BF4\u660E\u95EE\u9898\u3001\u4F9D\u636E\u548C\u4E0B\u4E00\u6B65\u64CD\u4F5C\u3002\n- \u7528\u6237\u786E\u8BA4\u4FDD\u5B58\u4E3A\u72EC\u7ACB\u6765\u6E90\uFF0C\u4FDD\u7559\u539F\u59CB\u5DE5\u5177\u8BB0\u5F55\uFF1B\u6279\u51C6\u64CD\u4F5C\u4E0D\u7B49\u4E8E\u5DF2\u7ECF\u6267\u884C\u6210\u529F\u3002\n- \u6CA1\u6709\u5F85\u5904\u7406\u4E8B\u9879\u65F6\u4E0D\u8F93\u51FA\u201C\u9700\u8981\u786E\u8BA4\u201D\u6216\u201C\u65E0\u5F85\u529E\u4E8B\u9879\u201D\u7AE0\u8282\u3002\n\n\u754C\u9762\u7684\u5B8C\u6210\u52FE\u3001\u5931\u8D25\u6807\u8BB0\u3001\u8B66\u544A\u6807\u8BB0\u548C\u8FD0\u884C\u6D41\u5149\u7531\u63D2\u4EF6\u6309\u771F\u5B9E\u72B6\u6001\u6E32\u67D3\uFF1B\u4EFB\u52A1\u5B8C\u6210\u540E\u79FB\u9664\u6D41\u5149\u4E0E\u56FA\u5B9A\u9AD8\u5149\u3002\u8BF7\u4FDD\u6301\u5185\u5BB9\u7ED3\u6784\u548C\u72B6\u6001\u8BED\u4E49\u4E00\u81F4\uFF0C\u5C0A\u91CD\u7528\u6237\u81EA\u5DF1\u7684\u914D\u8272\u3002\n";

